[{"order":1,"type":"heading","text":"PHP Properties and Methods: Access Modifiers"},{"order":2,"type":"paragraph","text":"In PHP, properties and methods control the data and behavior of a class. Access modifiers determine the visibility and accessibility of these members from different parts of the code. PHP supports three access modifiers: `public`, `private`, and `protected`."},{"order":3,"type":"subheading","text":"Public Access Modifier"},{"order":4,"type":"paragraph","text":"Members declared as `public` are accessible from anywhere – within the class, from other classes, and from outside the class. This offers the least restriction."},{"order":5,"type":"code","text":"<?php
class MyClass {
 public $publicProperty = 'This is a public property';

 public function publicMethod() {
 return 'This is a public method';
 }
}

$obj = new MyClass();
echo $obj->publicProperty . "\n"; // Output: This is a public property
echo $obj->publicMethod() . "\n"; // Output: This is a public method
?>"},{"order":6,"type":"subheading","text":"Private Access Modifier"},{"order":7,"type":"paragraph","text":"Members declared as `private` are only accessible from within the class that defines them. They cannot be accessed from outside the class, not even from subclasses."},{"order":8,"type":"code","text":"<?php
class MyClass {
 private $privateProperty = 'This is a private property';

 private function privateMethod() {
 return 'This is a private method';
 }

 public function accessPrivate() {
 return $this->privateProperty . ' and ' . $this->privateMethod();
 }
}

$obj = new MyClass();
// echo $obj->privateProperty; // Fatal error: Cannot access private property
// echo $obj->privateMethod(); // Fatal error: Cannot access private method
echo $obj->accessPrivate() . "\n"; // Output: This is a private property and This is a private method

class AnotherClass extends MyClass {
 public function tryAccessPrivate() {
 // return $this->privateProperty; // Fatal error: Cannot access private property
 return 'Cannot access private property from subclass';
 }
}

$anotherObj = new AnotherClass();
echo $anotherObj->tryAccessPrivate() . "\n";
?>"},{"order":9,"type":"subheading","text":"Protected Access Modifier"},{"order":10,"type":"paragraph","text":"Members declared as `protected` are accessible from within the class that defines them and from its subclasses (inherited classes). They are not accessible from outside the class hierarchy."},{"order":11,"type":"code","text":"<?php
class MyClass {
 protected $protectedProperty = 'This is a protected property';

 protected function protectedMethod() {
 return 'This is a protected method';
 }

 public function accessProtected() {
 return $this->protectedProperty . ' and ' . $this->protectedMethod();
 }
}

$obj = new MyClass();
// echo $obj->protectedProperty; // Fatal error: Cannot access protected property
// echo $obj->protectedMethod(); // Fatal error: Cannot access protected method
echo $obj->accessProtected() . "\n"; // Output: This is a protected property and This is a protected method

class AnotherClass extends MyClass {
 public function accessProtectedFromSubclass() {
 return $this->protectedProperty . ' and ' . $this->protectedMethod();
 }
}

$anotherObj = new AnotherClass();
echo $anotherObj->accessProtectedFromSubclass() . "\n"; // Output: This is a protected property and This is a protected method
?>"},{"order":12,"type":"subheading","text":"Summary Table"},{"order":13,"type":"bullet_point","text":"**Public:** Accessible from anywhere."},{"order":14,"type":"bullet_point","text":"**Private:** Accessible only from within the defining class."},{"order":15,"type":"bullet_point","text":"**Protected:** Accessible from within the defining class and its subclasses."},{"order":16,"type":"paragraph","text":"Choosing the appropriate access modifier is crucial for encapsulation and maintaining the integrity of your classes. Use the most restrictive access modifier that still allows the necessary functionality."}]
